platform-vs-devops-boundary.code:
{
  "apiVersion": "backstage.io/v1beta3",
  "kind": "Template",
  "metadata": { "name": "golden-path-service", "title": "New Service (Paved Path)" },
  "spec": {
    "owner": "platform-team",
    "paves": {
      "repo":          { "owner": "platform", "proof": "repo scaffolded from template" },
      "cicd":          { "owner": "platform", "proof": "first pipeline run green" },
      "environment":   { "owner": "platform", "proof": "terraform plan clean, env created" },
      "secrets":       { "owner": "platform", "proof": "vault path bound, no plaintext" },
      "observability": { "owner": "platform", "proof": "otel collector config validates" },
      "support":       { "owner": "platform", "proof": "runbook + on-call rotation set" }
    },
    "teamOwns": ["business logic", "service-level SLOs", "feature rollout decisions"],
    "boundary": {
      "nonNegotiable": "no service ships without a named on-call owner",
      "invalidatesIf": "any 'paves' entry has no proof — then the path is a portal, not a platform"
    },
    "adoption": { "metric": "% new services via template", "target": 0.8 }
  }
}

developer-journey-mapping.code:
{
  "apiVersion": "scaffolder.backstage.io/v1beta3",
  "kind": "Template",
  "metadata": { "name": "golden-path-service", "title": "New Service (Golden Path)" },
  "spec": {
    "parameters": { "name": "payments-api", "owner": "team-payments", "tier": "1" },
    "golden_path": {
      "template": "k8s Deployment + Service + HPA (rendered)",
      "cicd": ".github/workflows/deploy.yaml (green on first push)",
      "environment": "terraform: namespace + IAM role + DB (terraform plan)",
      "secrets": "external-secrets: vault path bound at deploy, never in git",
      "observability": "otel sidecar + dashboard auto-provisioned",
      "support": "runbook.md + on-call route generated"
    }
  }
}
# Proof hooks (run before merge):
#   kubectl apply --dry-run=server -f rendered/deployment.yaml   -> valid, no apply
#   terraform plan                                               -> env + IAM, 0 to destroy
#   helm template .                                              -> renders, no undefined values

logging-metrics-traces.code:
receivers:
  otlp:
    protocols:
      grpc: { endpoint: 0.0.0.0:4317 }
processors:
  batch: { timeout: 5s }
  resource:
    attributes:
      - key: service.name
        value: ${SERVICE_NAME}   # injected by the template
        action: upsert
exporters:
  otlp/traces: { endpoint: tempo:4317, tls: { insecure: true } }
  prometheus:  { endpoint: 0.0.0.0:9464 }   # metrics scrape target
  loki:        { endpoint: http://loki:3100/otlp }
service:
  pipelines:
    traces:  { receivers: [otlp], processors: [batch, resource], exporters: [otlp/traces] }
    metrics: { receivers: [otlp], processors: [batch, resource], exporters: [prometheus] }
    logs:    { receivers: [otlp], processors: [batch, resource], exporters: [loki] }
